SELECT percentile_cont(0.75) within GROUP (ORDER BY male_inpatients_with_ami_los.los) AS percentile_75, COUNT(DISTINCT CASE WHEN male_inpatients_with_ami_los.deathtime IS NOT NULL THEN male_inpatients_with_ami_los.subject_id END) AS critical_labs, COUNT(DISTINCT CASE WHEN male_inpatients_with_ami_los.deathtime IS NULL THEN male_inpatients_with_ami_los.subject_id END) AS total_labs, SUM(male_inpatients_with_ami_los.los) AS total_los, SUM(CASE WHEN male_inpatients_with_ami_los.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS mortality_count FROM male_inpatients_with_ami_los;